    def fmt(ws):
        return str(len(ws)) + '\n' + ' '.join(map(str, ws))
    tests = [fmt([5]), fmt([1, 1]), fmt([1, 1, 1]), fmt([1, 1, 1, 1, 1, 1]), fmt([10**9] * 3), fmt([3, 1, 2]),
             fmt([1] * 10)]
    for n in (2, 3, 4, 5, 6, 7, 8, 9):
        for _ in range(3):
            hi = rng.choice([1, 3, 20, 10**9])
            tests.append(fmt([rng.randint(1, hi) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(100000)]))
    tests.append(fmt([10**9] * 100000))
    tests.append(fmt([1] * 100000))
    k = 446
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(k * (k + 1) // 2)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(k * (k + 1) // 2 - 1)]))
    return tests

